function svgCard(title, style, svg, ol) {
  return `<div class="svg-card"><div class="svg-card-head"><span class="svg-card-title">${title}</span><label class="svg-card-replay"><input type="checkbox" data-replay/>Replay</label></div><style>${style}</style><div class="svg-anim anim ${svg.scopeClass} playing" style="--T:${svg.duration}s"><svg class="s-cs-svg" viewBox="${svg.viewBox}">${svg.inner}</svg>${ol ? `<ol class="s-cst">${ol}</ol>` : ''}</div></div>`;
}

